func:
node.status({ fill: 'blue', shape: 'ring', text: 'Loading...' });
return [
    { filename: '/userdata/config/device_config.json' },
    { filename: '/userdata/config/roi_config.json' }
];

try {
    const cfg = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
    if (cfg && cfg.device_id) {
        global.set('device_config', cfg);
        node.status({ fill: 'green', shape: 'dot', text: cfg.device_id });
    }
} catch(e) {
    node.warn('Device config parse: ' + e.message);
}
return null;

try {
    const cfg = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
    let final = null;
    if (cfg && Array.isArray(cfg.polygon) && cfg.polygon.length >= 3) {
        const entryArea = cfg.entry_area === 'outside' ? 'outside' : 'inside';
        final = {
            polygon: cfg.polygon,
            count_edge_index: typeof cfg.count_edge_index === 'number' ? cfg.count_edge_index : -1,
            entry_area: entryArea,
            masks: Array.isArray(cfg.masks) ? cfg.masks : []
        };
    } else if (cfg && Array.isArray(cfg.rect) && cfg.rect.length === 4) {
        const x1 = cfg.rect[0], y1 = cfg.rect[1], x2 = cfg.rect[2], y2 = cfg.rect[3];
        const polygon = [[x1,y1],[x2,y1],[x2,y2],[x1,y2]];
        const edgeMap = { top: 0, right: 1, bottom: 2, left: 3 };
        const idx = (typeof edgeMap[cfg.count_edge] === 'number') ? edgeMap[cfg.count_edge] : 2;
        final = { polygon: polygon, count_edge_index: idx, entry_area: cfg.entry_area === 'outside' ? 'outside' : 'inside', masks: Array.isArray(cfg.masks) ? cfg.masks : [] };
    }
    if (final) {
        final.presence_polygon = Array.isArray(cfg.presence_polygon) ? cfg.presence_polygon : [];
        global.set('roi_config', final);
        node.status({ fill: 'green', shape: 'dot', text: 'ROI loaded (edge ' + final.count_edge_index + ')' });
    } else {
        global.set('roi_config', { polygon: [], count_edge_index: -1, entry_area: 'inside', masks: [] });
        node.status({ fill: 'yellow', shape: 'ring', text: 'no ROI yet' });
    }
} catch(e) {
    global.set('roi_config', { polygon: [], count_edge_index: -1, entry_area: 'inside', masks: [] });
    node.warn('ROI parse: ' + e.message);
}
return null;

const src = msg.error ? msg.error.source : {};
const errMsg = msg.error ? msg.error.message : 'unknown error';
if (src && src.id === 'maint_load_roi') {
    global.set('roi_config', { polygon: [], count_edge_index: -1, entry_area: 'inside', masks: [] });
    node.status({ fill: 'yellow', shape: 'ring', text: 'no ROI yet' });
}
if (src && src.id === 'maint_load_dev') {
    global.set('device_config', { device_id: '', door_label: '' });
    node.status({ fill: 'yellow', shape: 'ring', text: 'no device cfg' });
}
if (src && (src.id === 'file_write_binary' || src.id === 'file_write')) {
    node.status({ fill: 'red', shape: 'ring', text: 'file write failed' });
    return { topic: 'capture_error', payload: { error: errMsg, source: src.name || src.id } };
}
return null;

// Maintenance V2: custom person model runs continuously; ROI dashboard filters and counts person only.
node.status({ fill: 'green', shape: 'dot', text: 'custom human model running v2' });
return null;

if (msg.topic === 'get_device') {
    const cfg = global.get('device_config') || { device_id: '', door_label: '' };
    return [{ topic: 'device_loaded', payload: cfg }, null];
}
if (msg.topic === 'save_device') {
    const cfg = msg.payload || {};
    if (!cfg.device_id) return null;
    global.set('device_config', cfg);
    node.status({ fill: 'green', shape: 'dot', text: 'Saved ' + cfg.device_id });
    return [null, {
        filename: '/userdata/config/device_config.json',
        payload: JSON.stringify(cfg, null, 2)
    }];
}
return null;

if (msg.topic === 'get_roi') {
    const cfg = global.get('roi_config') || { polygon: [], count_edge_index: -1, entry_area: 'inside', masks: [] };
    return [{ topic: 'roi_loaded', payload: cfg }, null, null, null];
}
if (msg.topic === 'save_roi') {
    const cfg = msg.payload;
    if (!cfg || !Array.isArray(cfg.polygon) || cfg.polygon.length < 3) return null;
    const N = cfg.polygon.length;
    if (typeof cfg.count_edge_index !== 'number' || cfg.count_edge_index < 0 || cfg.count_edge_index >= N) return null;
    cfg.entry_area = cfg.entry_area === 'outside' ? 'outside' : 'inside';
    if (!Array.isArray(cfg.masks)) cfg.masks = [];
    if (!Array.isArray(cfg.presence_polygon)) cfg.presence_polygon = [];
    if (cfg.presence_polygon.length > 0 && cfg.presence_polygon.length < 3) return null;
    global.set('roi_config', cfg);
    node.status({ fill: 'green', shape: 'dot', text: 'ROI saved (edge ' + cfg.count_edge_index + ')' });
    return [null, { filename: '/userdata/config/roi_config.json', payload: JSON.stringify(cfg, null, 2) }, null, null];
}
if (msg.topic === 'save_training_image') {
    try {
        const p = msg.payload || {};
        const raw = String(p.image || '').replace(new RegExp('^data:image/[^;]+;base64,'), '');
        if (!raw) return [{ topic: 'capture_error', payload: { error: 'no image frame available' } }, null, null, null];
        const jpg = Buffer.from(raw, 'base64');
        if (jpg.length < 4 || jpg[0] !== 0xff || jpg[1] !== 0xd8) return [{ topic: 'capture_error', payload: { error: 'frame is not valid JPEG data' } }, null, null, null];
        let label = String(p.label || 'person').trim().replace(/[^a-zA-Z0-9_-]/g, '_');
        if (!label) label = 'person';
        label = label.slice(0, 40);
        const ts = new Date().toISOString().replace(/[:.]/g, '-');
        const base = '/userdata/training_images/' + label + '/internal_capture_' + label + '_' + ts;
        const meta = { label, captured_at: new Date().toISOString(), polygon: Array.isArray(p.polygon) ? p.polygon : null, count_edge_index: typeof p.count_edge_index === 'number' ? p.count_edge_index : null, entry_area: p.entry_area === 'outside' ? 'outside' : 'inside', format: 'jpeg', bytes: jpg.length };
        node.status({ fill: 'green', shape: 'dot', text: 'captured ' + label });
        return [
            { topic: 'capture_queued', payload: { filename: base + '.jpg', bytes: jpg.length } },
            { filename: base + '.json', payload: JSON.stringify(meta, null, 2) },
            { filename: base + '.jpg', payload: jpg, capture_filename: base + '.jpg', capture_bytes: jpg.length },
            null
        ];
    } catch (e) {
        node.warn('Training image capture failed: ' + e.message);
        return [{ topic: 'capture_error', payload: { error: e.message } }, null, null, null];
    }
}
if (msg.topic === 'archive_training_folder') {
    const p = msg.payload || {};
    let label = String(p.label || 'person').trim().replace(/[^a-zA-Z0-9_-]/g, '_');
    if (!label) label = 'person';
    label = label.slice(0, 40);
    const ts = new Date().toISOString().replace(/[:.]/g, '-');
    const archiveName = 'internal_training_' + label + '_' + ts + '.tar.gz';
    const archiveFile = '/userdata/training_archives/' + archiveName;
    const imageDir = '/userdata/training_images/' + label;
    const cmd = '-c "mkdir -p /userdata/training_archives && test -d ' + imageDir + ' && tar -C /userdata/training_images -czf ' + archiveFile + ' ' + label + '"';
    node.status({ fill: 'blue', shape: 'ring', text: 'archiving ' + label });
    return [
        { topic: 'archive_queued', payload: { filename: archiveFile } },
        null,
        null,
        { payload: cmd, archive_filename: archiveFile, archive_name: archiveName, archive_label: label }
    ];
}
return null;

const filename = msg.capture_filename || msg.filename || '';
const bytes = msg.capture_bytes || (Buffer.isBuffer(msg.payload) ? msg.payload.length : undefined);
node.status({ fill: 'green', shape: 'dot', text: 'saved image' });
return { topic: 'capture_saved', payload: { filename, bytes } };

if (typeof msg.payload === 'string') {
    const text = msg.payload.trim();
    if (text) node.status({ fill: 'grey', shape: 'ring', text: text.slice(0, 40) });
    return null;
}
const code = typeof msg.payload === 'number' ? msg.payload : (msg.payload && typeof msg.payload.code === 'number' ? msg.payload.code : undefined);
if (code === 0) {
    const filename = msg.archive_filename || '';
    const archiveName = msg.archive_name || (filename.split('/').pop());
    node.status({ fill: 'green', shape: 'dot', text: 'archive ready' });
    return { topic: 'archive_ready', payload: { filename, url: '/training_archive/' + archiveName } };
}
if (code !== undefined) {
    node.status({ fill: 'red', shape: 'ring', text: 'archive failed' });
    return { topic: 'archive_error', payload: { error: 'tar failed with code ' + code } };
}
return null;

const name = String((msg.req && msg.req.params && msg.req.params.name) || '').replace(/[^a-zA-Z0-9_.-]/g, '');
if (!name || !name.endsWith('.tar.gz')) {
    msg.statusCode = 400;
    msg.payload = 'Bad archive name';
    return [null, msg];
}
msg.filename = '/userdata/training_archives/' + name;
msg.headers = {
    'Content-Type': 'application/gzip',
    'Content-Disposition': 'attachment; filename="' + name + '"'
};
return [msg, null];
